import argparse
import json
import re
import sys
from collections import Counter
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Iterable, List, Optional


WORD_RE = re.compile(r"\b[\w']+\b", re.UNICODE)


@dataclass
class TextStats:
    path: Optional[Path]
    lines: int
    words: int
    characters: int
    unique_words: int
    top_words: List[tuple[str, int]]
    token_counts: Counter[str] = field(repr=False, compare=False)


def tokenize(text: str) -> List[str]:
    return [m.group(0).lower() for m in WORD_RE.finditer(text)]


def analyze_text(
    text: str, path: Optional[Path], top_n: int
) -> TextStats:
    characters = len(text)
    lines = len(text.splitlines())
    tokens = tokenize(text)
    words = len(tokens)
    token_counts = Counter(tokens)
    unique_words = len(token_counts)
    top_words = token_counts.most_common(top_n)
    return TextStats(
        path=path,
        lines=lines,
        words=words,
        characters=characters,
        unique_words=unique_words,
        top_words=top_words,
        token_counts=token_counts,
    )


def read_text_from_file(path: Path) -> str:
    with path.open("r", encoding="utf-8") as fh:
        return fh.read()


def analyze_path(path: Path, top_n: int) -> TextStats:
    text = read_text_from_file(path)
    return analyze_text(text, path, top_n)


def analyze_stdin(top_n: int) -> TextStats:
    text = sys.stdin.read()
    return analyze_text(text, None, top_n)


def aggregate_stats(
    stats_list: List[TextStats], top_n: int
) -> TextStats:
    total_lines = sum(s.lines for s in stats_list)
    total_words = sum(s.words for s in stats_list)
    total_characters = sum(s.characters for s in stats_list)
    agg_counts: Counter[str] = Counter()
    for s in stats_list:
        agg_counts.update(s.token_counts)
    unique_words = len(agg_counts)
    top_words = agg_counts.most_common(top_n)
    return TextStats(
        path=None,
        lines=total_lines,
        words=total_words,
        characters=total_characters,
        unique_words=unique_words,
        top_words=top_words,
        token_counts=agg_counts,
    )


def stats_to_dict(stats: TextStats) -> dict[str, Any]:
    return {
        "path": None if stats.path is None else str(stats.path),
        "lines": stats.lines,
        "words": stats.words,
        "characters": stats.characters,
        "unique_words": stats.unique_words,
        "top_words": stats.top_words,
    }


def print_human_readable(
    stats_list: List[TextStats], total: Optional[TextStats]
) -> None:
    for s in stats_list:
        label = "<stdin>" if s.path is None else str(s.path)
        print(f"File: {label}")
        print(f"  Lines        : {s.lines}")
        print(f"  Words        : {s.words}")
        print(f"  Characters   : {s.characters}")
        print(f"  Unique words : {s.unique_words}")
        if s.top_words:
            print("  Top words:")
            for word, count in s.top_words:
                print(f"    {word:<20} {count}")
        print()
    if total and len(stats_list) > 1:
        print("Total:")
        print(f"  Lines        : {total.lines}")
        print(f"  Words        : {total.words}")
        print(f"  Characters   : {total.characters}")
        print(f"  Unique words : {total.unique_words}")
        if total.top_words:
            print("  Top words:")
            for word, count in total.top_words:
                print(f"    {word:<20} {count}")


def parse_args(argv: Optional[Iterable[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Compute text statistics for files or stdin."
    )
    parser.add_argument(
        "paths",
        nargs="*",
        help="Paths to text files. Use '-' to read from stdin.",
    )
    parser.add_argument(
        "--top",
        type=int,
        default=10,
        help="Number of most common words to show (default: 10).",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Output results in JSON format.",
    )
    return parser.parse_args(list(argv) if argv is not None else None)


def main() -> None:
    args = parse_args()
    top_n: int = max(0, args.top)

    paths_args: List[str] = args.paths
    if not paths_args:
        # If no paths are provided, read from stdin
        paths_args = ["-"]

    stats_list: List[TextStats] = []
    had_error = False

    for p in paths_args:
        if p == "-":
            try:
                stats = analyze_stdin(top_n)
                stats_list.append(stats)
            except Exception as exc:  # noqa: BLE001
                print(f"Error reading stdin: {exc}", file=sys.stderr)
                had_error = True
        else:
            path = Path(p)
            try:
                stats = analyze_path(path, top_n)
                stats_list.append(stats)
            except FileNotFoundError:
                print(f"File not found: {path}", file=sys.stderr)
                had_error = True
            except PermissionError:
                print(f"Permission denied: {path}", file=sys.stderr)
                had_error = True
            except UnicodeDecodeError:
                print(
                    f"Decoding error (expected UTF-8): {path}",
                    file=sys.stderr,
                )
                had_error = True
            except IsADirectoryError:
                print(f"Is a directory: {path}", file=sys.stderr)
                had_error = True
            except Exception as exc:  # noqa: BLE001
                print(f"Error reading {path}: {exc}", file=sys.stderr)
                had_error = True

    total_stats: Optional[TextStats] = None
    if len(stats_list) > 1:
        total_stats = aggregate_stats(stats_list, top_n)

    if args.json:
        payload: dict[str, Any] = {
            "files": [stats_to_dict(s) for s in stats_list],
        }
        if total_stats is not None:
            payload["total"] = stats_to_dict(total_stats)
        print(json.dumps(payload, ensure_ascii=False, indent=2))
    else:
        print_human_readable(stats_list, total_stats)

    if had_error:
        sys.exit(1)


if __name__ == "__main__":
    main()

