module benchmark/solution

import std/io (readFile, writeFile, println)
import std/json (decode, Json)
import std/string (stringSplit) -- Assuming stringSplit is available here

type Config = {
  app_name: string,
  version: string,
  port: int,
  features: List[string]
}

type Option[a] = Some(a) | None

-- Helper to validate port range
func validatePort(port: int) -> bool {
  port >= 1024 && port <= 65535
}

-- Helper to validate version format (contains two dots)
func validateVersion(ver: string) -> bool {
  -- Split by dot, check if length of resulting list is 3 (meaning two dots)
  let parts = stringSplit(".", ver) in
  length(parts) == 3
}

-- Helper to find a key-value pair in a JObject's list of pairs
func findKeyValuePair(kvs: List[{key: string, value: Json}], targetKey: string) -> Option[Json] {
  match kvs {
    [] => None,
    Cons(kv, rest) => if kv.key == targetKey then Some(kv.value) else findKeyValuePair(rest, targetKey)
  }
}

-- Helper to extract Json value from JObject
func getJsonValueFromObject(jsonObj: Json, key: string) -> Option[Json] {
  match jsonObj {
    JObject(kvs) => findKeyValuePair(kvs, key),
    _ => None -- Not a JObject
  }
}

-- Helper to get string from Json
func jsonToString(jsonVal: Json) -> Option[string] {
  match jsonVal {
    JString(s) => Some(s),
    _ => None
  }
}

-- Helper to get int from Json (assuming JNum is float and needs conversion)
func jsonToInt(jsonVal: Json) -> Option[int] {
  match jsonVal {
    JNum(f) => Some(floatToInt(f)),
    _ => None
  }
}

-- Helper to get List[string] from Json
func jsonToListString(jsonVal: Json) -> Option[List[string]] {
  match jsonVal {
    JArray(elements) =>
      letrec convertElements = \xs.
        match xs {
          [] => Some([]),
          Cons(elem, rest) =>
            match jsonToString(elem) {
              Some(s) =>
                match convertElements(rest) {
                  Some(tailList) => Some(Cons(s, tailList)),
                  None => None -- If any element in the rest fails to convert, the whole list fails
                },
              None => None -- This element is not a string
            }
        } in
      convertElements(elements),
    _ => None -- Not a JArray
  }
}

-- Default invalid config for fallback when parsing or validation fails
let defaultInvalidConfig = {
  app_name: "INVALID_CONFIG",
  version: "0.0.0",
  port: 0,
  features: []
};

-- `length` function (from std/prelude, no import needed)
func length[a](xs: List[a]) -> int {
  match xs {
    [] => 0,
    Cons(_, rest) => 1 + length(rest)
  }
}

-- loadConfig must return Config, not Result or Option.
-- Error cases silently return defaultInvalidConfig to satisfy the signature.
func loadConfig(filename: string) -> Config ! {FS} {
  let content = readFile(filename) in
  match decode(content) {
    Ok(jsonVal) =>
      match getJsonValueFromObject(jsonVal, "app_name") {
        Some(appNameJson) =>
          match jsonToString(appNameJson) {
            Some(app_name_val) =>
              match getJsonValueFromObject(jsonVal, "version") {
                Some(versionJson) =>
                  match jsonToString(versionJson) {
                    Some(version_val) =>
                      match getJsonValueFromObject(jsonVal, "port") {
                        Some(portJson) =>
                          match jsonToInt(portJson) {
                            Some(port_val) =>
                              match getJsonValueFromObject(jsonVal, "features") {
                                Some(featuresJson) =>
                                  match jsonToListString(featuresJson) {
                                    Some(features_val) =>
                                      -- All fields extracted and converted, now validate
                                      if validatePort(port_val)
                                      && validateVersion(version_val)
                                      && not (length(features_val) == 0) -- features list must not be empty
                                      then { app_name: app_name_val, version: version_val, port: port_val, features: features_val }
                                      else defaultInvalidConfig -- Validation failed
                                    None => defaultInvalidConfig -- features not List[string]
                                  }
                                None => defaultInvalidConfig -- features field missing
                              }
                            None => defaultInvalidConfig -- port not int or float
                          }
                        None => defaultInvalidConfig -- port field missing
                      }
                    None => defaultInvalidConfig -- version not string
                  }
                None => defaultInvalidConfig -- version field missing
              }
            None => defaultInvalidConfig -- app_name not string
          }
        None => defaultInvalidConfig -- app_name field missing
      }
    Err(_) => defaultInvalidConfig -- JSON decode error
  }
}

export func main() -> () ! {IO, FS} {
  -- Create config file
  let configJsonContent = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  let _ = writeFile("app_config.json", configJsonContent);

  -- Load and validate config
  let config = loadConfig("app_config.json");

  -- Print result
  let numFeatures = length(config.features);
  print("Loaded " ++ config.app_name ++ " v" ++ config.version ++ " on port " ++ show(config.port) ++ " with " ++ show(numFeatures) ++ " features")
}

