from dataclasses import dataclass
from typing import List
import json
from pathlib import Path

@dataclass
class Config:
    app_name: str
    version: str
    port: int
    features: List[str]

class ConfigError(Exception):
    """Base exception for configuration errors."""
    pass

class FileReadError(ConfigError):
    """Raised when the configuration file cannot be read."""
    pass

class JsonParseError(ConfigError):
    """Raised when the configuration file contains invalid JSON."""
    pass

class InvalidPortError(ConfigError):
    """Raised when the port is out of the valid range."""
    pass

class InvalidVersionError(ConfigError):
    """Raised when the version string does not match the expected format."""
    pass

class EmptyFeaturesError(ConfigError):
    """Raised when the features list is empty."""
    pass

def load_config(filename: Path) -> Config:
    try:
        content = filename.read_text(encoding="utf-8")
    except FileNotFoundError:
        raise FileReadError(f"Configuration file not found: {filename}")
    except IOError as e:
        raise FileReadError(f"Error reading configuration file {filename}: {e}")

    try:
        data = json.loads(content)
    except json.JSONDecodeError as e:
        raise JsonParseError(f"Error parsing JSON from {filename}: {e}")

    try:
        app_name = data["app_name"]
        version = data["version"]
        port = data["port"]
        features = data["features"]
    except KeyError as e:
        raise ConfigError(f"Missing required key in config file: {e}")
    except TypeError as e:
        raise ConfigError(f"Type error during field extraction: {e}")

    if not isinstance(app_name, str):
        raise ConfigError("app_name must be a string.")
    if not isinstance(version, str):
        raise ConfigError("version must be a string.")
    if not isinstance(port, int):
        raise ConfigError("port must be an integer.")
    if not isinstance(features, list) or not all(isinstance(f, str) for f in features):
        raise ConfigError("features must be a list of strings.")

    if not (1024 <= port <= 65535):
        raise InvalidPortError(f"Port {port} is out of valid range (1024-65535).")

    if version.count(".") != 2:
        raise InvalidVersionError(f"Version '{version}' does not match 'X.Y.Z' format.")

    if not features:
        raise EmptyFeaturesError("Features list cannot be empty.")

    return Config(app_name=app_name, version=version, port=port, features=features)

def main() -> None:
    config_file_name = "app_config.json"
    config_path = Path(config_file_name)

    initial_config_data = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "port": 8080,
        "features": ["logging", "auth", "api"]
    }
    try:
        config_path.write_text(json.dumps(initial_config_data, indent=2), encoding="utf-8")
    except IOError as e:
        print(f"Error creating config file '{config_file_name}': {e}")
        return

    try:
        config = load_config(config_path)
        num_features = len(config.features)
        print(f"Loaded {config.app_name} v{config.version} on port {config.port} with {num_features} features")
    except ConfigError as e:
        print(f"Configuration error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

