from typing import TypeVar, Callable, Generic

T = TypeVar('T')
R = TypeVar('R')

class Pure(Generic[T]):
    """Wrapper for pure values that can only be used in pure contexts"""
    def __init__(self, value: T):
        self._value = value

    def get(self) -> T:
        return self._value

class Effect(Generic[T]):
    """Wrapper for effectful computations"""
    def __init__(self, computation: Callable[[], T]):
        self._computation = computation

    def run(self) -> T:
        return self._computation()

def double(x: int) -> Pure[int]:
    """PURE: Returns x * 2"""
    return Pure(x * 2)

def add(a: int, b: int) -> Pure[int]:
    """PURE: Returns a + b"""
    return Pure(a + b)

def printResult(label: str, value: int) -> Effect[None]:
    """EFFECTFUL: Prints label: value"""
    def _print():
        print(f"{label}: {value}")
    return Effect(_print)

def compute_and_print() -> Effect[None]:
    """EFFECTFUL: Computes and prints result"""
    def _compute():
        result1 = double(5).get()
        result2 = add(result1, 3).get()
        printResult("Result", result2).run()
    return Effect(_compute)

if __name__ == "__main__":
    compute_and_print().run()

