from dataclasses import dataclass
from typing import Generic, TypeVar, Union

T = TypeVar('T')

@dataclass(frozen=True)
class Ok(Generic[T]):
    """Represents a successful result with a value."""
    value: T

@dataclass(frozen=True)
class Err:
    """Represents a failed result with an error message."""
    message: str

Result = Union[Ok[T], Err]

def parse_int(s: str) -> Result[int]:
    """
    Attempts to parse a string into an integer.

    Returns Ok(n) if successful, Err("Invalid integer") otherwise.
    """
    try:
        n = int(s)
        return Ok(n)
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int]:
    """
    Divides two integers safely, preventing division by zero.

    Returns Ok(a // b) if b is not zero, Err("Division by zero") otherwise.
    Uses integer division.
    """
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def main() -> None:
