    parsed_value_result_1 = parse_int("10")
    final_result_1: Result[int]
    if isinstance(parsed_value_result_1, Ok):
        final_result_1 = divide_safe(parsed_value_result_1.value, 2)
    else:
        final_result_1 = parsed_value_result_1  # Propagate the error

    if isinstance(final_result_1, Ok):
        print(f"Result: {final_result_1.value}")
    else:
        print(f"Error: {final_result_1.message}")

