import collections
import string
import sys
from pathlib import Path


def count_words(file_path: Path) -> dict[str, int]:
    """
    Counts the frequency of words in a given text file.

    Words are converted to lowercase and stripped of punctuation.
    """
    if not file_path.is_file():
        raise FileNotFoundError(f"Input file not found: {file_path}")

    word_counts: collections.Counter[str] = collections.Counter()
    try:
        with file_path.open(mode="r", encoding="utf-8") as f:
            for line in f:
                words_in_line = [
                    word.strip(string.punctuation).lower()
                    for word in line.split()
                    if word.strip(string.punctuation)
                ]
                word_counts.update(words_in_line)
    except IOError as e:
        raise IOError(f"Error reading file {file_path}: {e}") from e

    return dict(word_counts)


def write_counts(counts: dict[str, int], output_path: Path) -> None:
    """
    Writes word counts to an output file, one word and its count per line.
    """
    try:
        with output_path.open(mode="w", encoding="utf-8") as f:
            for word, count in sorted(counts.items()):
                f.write(f"{word}: {count}\n")
    except IOError as e:
        raise IOError(f"Error writing to file {output_path}: {e}") from e


def main() -> None:
    """
    Main function to execute the word counting and writing process.
    """
    input_file_path = Path("input.txt")
    output_file_path = Path("word_counts.txt")

    # Create a dummy input file if it doesn't exist for demonstration purposes.
    if not input_file_path.is_file():
