module benchmark/solution

import std/io (readFile, writeFile)
import std/string (indexOf, slice, length) -- Assuming these exist in std/string or prelude

type Option[a] = Some(a) | None

type LogEntry = {
  timestamp: string,
  level: string,
  message: string
}

type LogStats = {
  total: int,
  info_count: int,
  error_count: int,
  warning_count: int,
  users: List[string]
}

-- Basic list helper functions (from prompt examples, adapted for internal use)
func map[a, b](f: func(a) -> b, xs: List[a]) -> List[b] {
  match xs {
    [] => [],
    Cons(x, rest) => Cons(f(x), map(f, rest))
  }
}

func filter[a](pred: func(a) -> bool, xs: List[a]) -> List[a] {
  match xs {
    [] => [],
    Cons(x, rest) =>
      if pred(x)
      then Cons(x, filter(pred, rest))
      else filter(pred, rest)
  }
}

func foldl[a, b](f: func(b, a) -> b, acc: b, xs: List[a]) -> b {
  match xs {
    [] => acc,
    Cons(x, rest) => foldl(f, f(acc, x), rest)
  }
}

func listLength[a](xs: List[a]) -> int {
  match xs {
    [] => 0,
    Cons(_, rest) => 1 + listLength(rest)
  }
}

-- Helper to reverse a list (needed for split and user list ordering)
func reverse[a](xs: List[a]) -> List[a] =
  letrec rev_acc = \list_param. \acc_param.
    match list_param {
      [] => acc_param,
      Cons(h, t) => rev_acc(t)(Cons(h, acc_param))
    } in
  rev_acc(xs)([])

-- Helper to split string
func splitHelper(s: string, delim: string, acc: List[string]) -> List[string] =
  let idx = indexOf(s, delim) in
  if idx == -1 then Cons(s, acc) -- Base case: delimiter not found, add remaining string
  else {
    let part = slice(s, 0, idx) in
    let rest = slice(s, idx + length(delim), length(s)) in
    splitHelper(rest, delim, Cons(part, acc))
  }

func split(s: string, delim: string) -> List[string] =
  reverse(splitHelper(s, delim, []))

-- Helper to parse a log line
func parseLogLine(line: string) -> LogEntry =
  let parts = split(line, " ") in
  match parts {
    Cons(date, Cons(time, Cons(level, rest))) => {
      let timestamp = date ++ " " ++ time in
      let message = foldl(\acc. \x. if acc == "" then x else acc ++ " " ++ x, "", rest) in
      {timestamp: timestamp, level: level, message: message}
    },
    _ => {timestamp: "", level: "UNKNOWN", message: line} -- Fallback for malformed lines
  }

-- Helper to check if list contains item
func contains[a](item: a, xs: List[a]) -> bool =
  match xs {
    [] => false,
    Cons(h, t) => if h == item then true else contains(item, t)
  }

-- Helper to add item uniquely to a list
func addUnique(list: List[string], item: string) -> List[string] =
  if contains(item, list) then list
  else Cons(item, list)

-- Helper to extract users from message
func extractUser(message: string) -> Option[string] =
  let login_prefix = "User logged in: " in
  let logout_prefix = "User logged out: " in

  let login_idx = indexOf(message, login_prefix) in
  if login_idx != -1 then
    let start_idx = login_idx + length(login_prefix) in
    Some(slice(message, start_idx, length(message)))
  else
    let logout_idx = indexOf(message, logout_prefix) in
    if logout_idx != -1 then
      let start_idx = logout_idx + length(logout_prefix) in
      Some(slice(message, start_idx, length(message)))
    else None

-- Helper to calculate percentage (rounded to nearest int for positive numbers)
func percentage(count: int, total: int) -> int =
  if total == 0 then 0 -- Avoid division by zero
  else (count * 100 + total / 2) / total

-- Main analysis function (recursive accumulator pattern)
func processEntries(lines: List[string], stats: LogStats) -> LogStats =
  match lines {
    [] => stats,
    Cons(line, rest) => {
      let entry = parseLogLine(line) in
      let new_info_count = if entry.level == "INFO" then stats.info_count + 1 else stats.info_count in
      let new_error_count = if entry.level == "ERROR" then stats.error_count + 1 else stats.error_count in
      let new_warning_count = if entry.level == "WARNING" then stats.warning_count + 1 else stats.warning_count in
      let user_opt = extractUser(entry.message) in
      let new_users =
        match user_opt {
          Some(user) => addUnique(stats.users, user),
          None => stats.users
        } in
      let new_stats = {
        total: stats.total + 1,
        info_count: new_info_count,
        error_count: new_error_count,
        warning_count: new_warning_count,
        users: new_users
      } in
      processEntries(rest, new_stats)
    }
  }

func analyzeLog(filename: string) -> LogStats ! {FS} =
  let content = readFile(filename) in
  let all_lines = split(content, "\n") in
  let non_empty_lines = filter(\l. length(l) > 0, all_lines) in
  let initial_stats = {
    total: 0,
    info_count: 0,
    error_count: 0,
    warning_count: 0,
    users: []
  } in
  processEntries(non_empty_lines, initial_stats)

-- Helper to join list of strings with a delimiter
func join(xs: List[string], delim: string) -> string =
  match xs {
    [] => "",
    Cons(h, []) => h,
    Cons(h, t) => h ++ delim ++ join(t, delim)
  }

export func main() -> () ! {IO, FS} {
  let logContent = "2024-10-29 10:00:00 INFO User logged in: alice\n2024-10-29 10:01:15 ERROR Database connection failed\n2024-10-29 10:02:30 INFO User logged in: bob\n2024-10-29 10:03:45 WARNING High memory usage: 85%\n2024-10-29 10:05:00 ERROR API timeout: /users endpoint\n2024-10-29 10:06:15 INFO User logged out: alice" in
  let _ = writeFile("app.log", logContent) in

  let stats = analyzeLog("app.log") in

  -- The problem asks for "alice, bob" order. My addUnique adds to the head (Cons(item, list)).
  -- So, `stats.users` will be `[bob, alice]` based on log order. Reverse it to get `[alice, bob]`.
  let sorted_users = reverse(stats.users) in
  let users_str = join(sorted_users, ", ") in

  print("Total log entries: " ++ show(stats.total));
  print("INFO: " ++ show(stats.info_count) ++ " (" ++ show(percentage(stats.info_count, stats.total)) ++ "%)");
  print("ERROR: " ++ show(stats.error_count) ++ " (" ++ show(percentage(stats.error_count, stats.total)) ++ "%)");
  print("WARNING: " ++ show(stats.warning_count) ++ " (" ++ show(percentage(stats.warning_count, stats.total)) ++ "%)");
  print("Unique users: " ++ users_str)
}

