import pathlib
import re
import math

def create_log_file(filename: pathlib.Path) -> None:
    log_content = """2024-10-29 10:00:00 INFO User logged in: alice
2024-10-29 10:01:15 ERROR Database connection failed
2024-10-29 10:02:30 INFO User logged in: bob
2024-10-29 10:03:45 WARNING High memory usage: 85%
2024-10-29 10:05:00 ERROR API timeout: /users endpoint
2024-10-29 10:06:15 INFO User logged out: alice"""
    filename.write_text(log_content)

def analyze_log_file(filename: pathlib.Path) -> dict:
    log_levels_count = {"INFO": 0, "ERROR": 0, "WARNING": 0}
    unique_users = set()
    total_entries = 0

    with filename.open("r") as f:
        for line in f:
            total_entries += 1
            raw_parts = line.strip().split(maxsplit=3) # Split into timestamp_date, timestamp_time, level, message

            if len(raw_parts) >= 3:
                level = raw_parts[2]
                if level in log_levels_count:
                    log_levels_count[level] += 1

                message_part = raw_parts[3] if len(raw_parts) > 3 else ""

                user_match = re.search(r'User logged (?:in|out): (\w+)', message_part)
                if user_match:
                    user = user_match.group(1)
                    if user in ("alice", "bob"):
                        unique_users.add(user)

    results = {
        "total": total_entries,
        "counts": log_levels_count,
        "users": sorted(list(unique_users))
    }
    return results

def calculate_percentage(count: int, total: int) -> int:
    if total == 0:
        return 0
    return round(count * 100 / total)

def main() -> None:
    log_file_path = pathlib.Path("app.log")

    create_log_file(log_file_path)
    stats = analyze_log_file(log_file_path)

    print(f"Total log entries: {stats['total']}")
    for level in ["INFO", "ERROR", "WARNING"]:
        count = stats['counts'].get(level, 0)
        percentage = calculate_percentage(count, stats['total'])
        print(f"{level}: {count} ({percentage}%)")

    print(f"Unique users: {', '.join(stats['users'])}")

if __name__ == "__main__":
    main()

