type Tree = Leaf(int) | Node(Tree, int, Tree)

export func tree_sum(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(l, v, r) => tree_sum(l) + v + tree_sum(r)
  }
}

export func find_max(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(Leaf(x), v, Leaf(y)) if v >= x && v >= y => v,
    Node(Leaf(x), v, Leaf(y)) if x >= y => x,
    Node(Leaf(x), v, Leaf(y)) => y,
    Node(l, v, r) => {
      let lmax = find_max(l);
      let rmax = find_max(r);
      if v >= lmax && v >= rmax
      then v
      else if lmax >= rmax
      then lmax
      else rmax
    }
  }
}

export func main() -> () ! {IO} {
  let tree = Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)));
  let s = tree_sum(tree);
  let m = find_max(tree);
  print("Sum: " ++ show(s));
  print("Max: " ++ show(m))
}

