from dataclasses import dataclass
from typing import Union


@dataclass(frozen=True)
class Green:
    timer: int


@dataclass(frozen=True)
class Yellow:
    timer: int


@dataclass(frozen=True)
class Red:
    timer: int


@dataclass(frozen=True)
class Tick:
    pass


@dataclass(frozen=True)
class Reset:
    pass


State = Union[Green, Yellow, Red]
Event = Union[Tick, Reset]


def transition(state: State, event: Event) -> State:
    if isinstance(event, Tick):
        if isinstance(state, Green):
            return Green(state.timer - 1) if state.timer > 0 else Yellow(3)
        if isinstance(state, Yellow):
            return Yellow(state.timer - 1) if state.timer > 0 else Red(10)
        if isinstance(state, Red):
            return Red(state.timer - 1) if state.timer > 0 else Green(20)
        raise TypeError(f"Unknown state: {state!r}")
    if isinstance(event, Reset):
        return Green(20)
    raise TypeError(f"Unknown event: {event!r}")


def show_state(state: State) -> str:
    if isinstance(state, Green):
        return f"GREEN ({state.timer}sec)"
    if isinstance(state, Yellow):
        return f"YELLOW ({state.timer}sec)"
    if isinstance(state, Red):
        return f"RED ({state.timer}sec)"
    raise TypeError(f"Unknown state: {state!r}")


def main() -> None:
    state: State = Green(20)

    # Apply 25 Tick events
    for _ in range(25):
        state = transition(state, Tick())
        print(show_state(state))

    # Apply 1 Reset event
    state = transition(state, Reset())
    print(show_state(state))

    # Apply 5 more Tick events
    for _ in range(5):
        state = transition(state, Tick())
        print(show_state(state))


if __name__ == "__main__":
    main()

