import std/io (println)

type Tree =
  | Leaf(int)
  | Node(Tree, int, Tree)

// Helper for list concatenation
func appendLists[a](xs: List[a], ys: List[a]) -> List[a] =
  match xs {
    [] => ys,
    Cons(h, t) => Cons(h, appendLists(t, ys))
  }

// Map: apply function to all values
func mapTree(fn: func(int) -> int, tree: Tree) -> Tree =
  match tree {
    Leaf(v) => Leaf(fn(v)),
    Node(left, v, right) =>
      Node(mapTree(fn, left), fn(v), mapTree(fn, right))
  }

// Fold: in-order traversal with accumulator, ignoring dummy 0 leaves
func foldTree(fn: func(int, int) -> int, acc: int, tree: Tree) -> int =
  match tree {
    Leaf(v) => if v == 0 then acc else fn(acc, v),
    Node(left, v, right) =>
      let accLeft = foldTree(fn, acc, left) in
      let accV = fn(accLeft, v) in
      foldTree(fn, accV, right)
  }

// Convert tree to list (in-order), filtering out dummy 0s
func treeToList(tree: Tree) -> List[int] =
  match tree {
    Leaf(v) => if v == 0 then [] else [v],
    Node(left, v, right) =>
      let leftList = treeToList(left) in
      let rightList = treeToList(right) in
      appendLists(appendLists(leftList, [v]), rightList)
  }

// Calculate tree depth
func treeDepth(tree: Tree) -> int =
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) =>
      let leftDepth = treeDepth(left) in
      let rightDepth = treeDepth(right) in
      1 + (if leftDepth > rightDepth then leftDepth else rightDepth)
  }

// Helper to format list as string
func showList(lst: List[int]) -> string =
  func innerShow(currentList: List[int]) -> string =
    match currentList {
      [] => "",
      Cons(h, []) => show(h),
      Cons(h, t) => show(h) ++ ", " ++ innerShow(t)
    } in
  "[" ++ innerShow(lst) ++ "]"

export func main() -> () ! {IO} =
  // Build example tree
  let tree = Node(
    Node(Leaf(1), 3, Leaf(0)),
    5,
    Node(Leaf(7), 8, Leaf(9))
  ) in

  // Print original tree values
  let original = treeToList(tree) in
  let _ = println("Original: " ++ showList(original)) in

  // Map: double all values
  let doubleFn = \x. x * 2 in
  let doubledTree = mapTree(doubleFn, tree) in
  let doubledList = treeToList(doubledTree) in
  let _ = println("Doubled: " ++ showList(doubledList)) in

  // Fold: sum all values
  let addFn = \a. \b. a + b in
  let sum = foldTree(addFn, 0, tree) in
  let _ = println("Sum: " ++ show(sum)) in

  // Depth
  let depth = treeDepth(tree) in
  println("Depth: " ++ show(depth))

